window.products.push({"id":387583,"name":"Discovery Homicide Hunter Joe Kenda Standee","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/61C9rcUVwYL._AC_SL1200_.jpg","description":"Homicide Hunter Joe Kenda is an expert in catching someone in a lie, so why wouldn't you want him around all the time? We've got just what you need: a Homicide Hunter life-size Joe Kenda standee. The 73-inch tall cardboard standee brings Lt. Kenda into your home, with his trademark scrutinizing stare and a no-nonsense stance that will keep all your friends and family on their best behavior. 73 inches tallMaterial: Cardboard","images":["https://m.media-amazon.com/images/I/61C9rcUVwYL._AC_SL1200_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Discovery","source_asin":"B00LC6JTA8","category_path":"Home & Kitchen"},"sku":"BM-387583","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00LC6JTA8","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00LC6JTA8","price_pending":true,"merchant_ready":false});
